    assert tax_for(1000, Decimal("0.08")) == 80


def test_tax_for_rounds_half_even():
    # 0.5 cent ties go to the even neighbour
    assert tax_for(50, Decimal("0.05")) == 2  # 2.5 -> 2
    assert tax_for(70, Decimal("0.05")) == 4  # 3.5 -> 4


def test_tax_for_accepts_float_and_str_rates():
    assert tax_for(1999, 0.0825) == 165  # 164.9175 -> 165
